// ROUND 22 -- which interior art files actually exist in public/assets.
//
// GENERATED by extract_round22_interiors.py once the user's interior art
// lands. Until then every flag is false and WorldScene builds a labelled
// PLACEHOLDER for that key instead (see _buildInteriorArt) -- same texture
// key, same frame layout, same origin convention, so swapping a placeholder
// for real art is a one-flag change and nothing else in the game moves.
//
// This exists rather than "just try to load the PNG and catch the 404"
// because a missing-file load is not free: it puts a real network error in
// the console on every boot, which is noise in exactly the place the
// project's regression tests look for genuine problems (the round-20
// missing-texture assertion). A manifest keeps the loader honest -- it only
// ever asks for files that are there.
export const INTERIOR_ART_PRESENT = {
  // ROUND 266 -- TRUE AT LAST, AND THAT IS THE WHOLE OF ITEM 3.
  //
  // These two flags have read `false` since round 22, which is this file's
  // way of saying "the art has not landed, paint a labelled placeholder".
  // Nothing ever landed. Measured: 93 rooms have a forge floor and 21 a
  // marble one, so 114 of the game's 174 interiors were standing on a flat
  // generated tone while every field outside was laid with a hand-drawn
  // 128px tile. tools/extract_round266_floors.py cuts all three out of the
  // Screaming Brain sets the outdoors is already made of.
  floorForge: true,
  floorMarble: true,
  floorHall: true,
  // ROUND 83 -- sewer_floor.png is real, written by
  // extract_round83_sewer_tiles.py from the grey city paving. Without this
  // flag the loader would skip the file and _buildInteriorArt would paint a
  // labelled placeholder over it -- which is what round 82's sewer floor
  // actually was, since `floorForge` it was borrowing is false right here.
  floorSewer: true,
  // ROUND 130 -- the soul space's one plain grass tile, cut out of the meadow
  // pack by tools/sheet_round128_garden.py. Without this flag the loader never
  // asks for the file and `_buildInteriorArt` falls through to the placeholder
  // path -- which reads FLOOR_TONES[name] unguarded and throws inside world
  // build. Measured: a black screen and no player sprite, which is the exact
  // failure the round-78 note in FLOOR_TONES warns about.
  soul_grass: true,
  wallBack: true,
  wallTrim: true,
  interiorProps: true,
  // ROUND 200 -- the six building kits, written by
  // tools/extract_round200_kits.py. One flag per material rather than one for
  // the set: they are six separate files, and a kit whose PNG did not make it
  // into a build should fall back to the labelled placeholder on its own
  // rather than taking the other five down with it.
  kit_log: true,
  kit_lava: true,
  kit_ice: true,
  kit_darkstone: true,
  kit_greenbrick: true,
  kit_greybrick: true,
};
